import subprocess


def _fecha_de_la_copia(ruta):
    """Devuelve la fecha de ultimo cambio del archivo en segundos, o None si no se puede."""
    try:
        return os.path.getmtime(ruta)
    except OSError:
        return None


def _fecha_del_ultimo_guardado_en_git(raiz, destino):
    """Pregunta a git la fecha del ultimo guardado del archivo, en segundos.

    Devuelve None si git no contesta o falla. Nunca revienta.
    """
    try:
        resultado = subprocess.run(
            ["git", "log", "-1", "--format=%ct", "--", destino],
            cwd=raiz,
            capture_output=True,
            text=True,
            timeout=10,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if resultado.returncode != 0:
        return None
    salida = (resultado.stdout or "").strip()
    if not salida:
        return None
    try:
        return int(salida)
    except ValueError:
        return None


def _es_vieja(raiz, destino, origen):
    """Dice si la copia apartada es de antes del ultimo guardado en git.

    Compara la fecha del ultimo guardado en git del archivo destino con la fecha de la
    copia apartada. Si git no contesta, devuelve False (se devuelve como hoy).
    """
    fecha_git = _fecha_del_ultimo_guardado_en_git(raiz, destino)
    if fecha_git is None:
        return False
    fecha_copia = _fecha_de_la_copia(origen)
    if fecha_copia is None:
        return False
    return fecha_git > fecha_copia
